from django.http import JsonResponse

from shop.models import Product


def search(request):
    q = request.GET.get('q', '')
    rows = Product.objects.filter(name__icontains=q)
    return JsonResponse({'results': [{'name': p.name, 'price': p.price} for p in rows]})
